/**
 * The UnoCSS probe's browser acceptance (alpha15 stage 2B).
 *
 * The build's artifacts are the unit tests' business; this suite reads the
 * REAL rendered document in a real engine and requires the two deliveries to
 * have taken effect:
 *
 * - the DOCUMENT sheet (generated by UnoCSS from the page's admitted class
 *   tokens and the Open Props token source) styles the light-root page's own
 *   markup, and the token source's own variable is the value the browser
 *   resolved;
 * - the COMPONENT sheet (generated from the shadow component's admitted class
 *   tokens) styles content inside the declarative shadow root, where a
 *   document-level rule cannot reach.
 *
 * Every assertion reads `getComputedStyle`, so a sheet that exists but does
 * not apply fails here.
 */
import { expect, test } from '@playwright/test';

/** The computed value of one property on one selector inside the document. */
async function computed(
  page: import('@playwright/test').Page,
  selector: string,
  property: string,
): Promise<string> {
  return await page.evaluate(
    ([sel, prop]) => {
      const node = document.querySelector(sel as string);
      if (node === null) throw new Error(`no element for ${sel}`);
      return getComputedStyle(node as Element)
        .getPropertyValue(prop as string)
        .trim();
    },
    [selector, property],
  );
}

test.beforeEach(async ({ page }) => {
  await page.goto('/');
});

test('the document sheet applies the page’s compiled utilities', async ({ page }) => {
  expect(await computed(page, 'probe-unocss-page main', 'max-width')).toBe('672px');
  expect(await computed(page, 'probe-unocss-page main', 'padding-top')).toBe('40px');
  expect(await computed(page, 'probe-unocss-page h1', 'font-weight')).toBe('600');
});

test('the token source’s own variable is what the utilities resolve to', async ({ page }) => {
  // `text-muted` compiles to `color-mix(… var(--color-muted) …)`, and
  // `--color-muted` is Open Props' `--gray-3` through the app's role table.
  // The assertion is on the RESOLVED colour, so a missing token source (which
  // would compute to the inherited colour) fails.
  const paragraph = await computed(page, 'probe-unocss-page p', 'color');
  const root = await page.evaluate(() =>
    getComputedStyle(document.documentElement).getPropertyValue('--color-muted').trim(),
  );
  expect(root, 'the token source reached the document').not.toBe('');
  expect(paragraph, 'the compiled utility resolved through the token variable').not.toBe(
    await computed(page, 'probe-unocss-page main', 'color'),
  );
});

test('the component sheet reaches inside the declarative shadow root', async ({ page }) => {
  const shadow = await page.evaluate(() => {
    const host = document.querySelector('probe-unocss-card');
    const root = host?.shadowRoot ?? null;
    const article = root?.querySelector('article') ?? null;
    if (article === null) return null;
    const style = getComputedStyle(article);
    const marker = root?.querySelector('.probe-marker');
    return {
      display: style.display,
      gap: style.gap,
      paddingLeft: style.paddingLeft,
      borderRadius: style.borderTopLeftRadius,
      backgroundColor: style.backgroundColor,
      markerColor: marker == null ? '' : getComputedStyle(marker).color,
    };
  });
  expect(shadow, 'the shadow root renders the control').not.toBeNull();
  expect(shadow!.display, 'the component sheet applies inside the shadow root').toBe('inline-flex');
  expect(shadow!.gap).toBe('8px');
  expect(shadow!.paddingLeft, 'px-3 compiled and applied').toBe('12px');
  expect(shadow!.borderRadius, 'rounded-lg compiled and applied').toBe('8px');
  // `bg-primary/14` compiles to `color-mix(… var(--color-primary) 14%, transparent)`.
  // Engines spell the result differently (`rgba(…)` in Chromium, `color(srgb … / 0.14)`
  // in Firefox and WebKit), so the assertion reads the HTML/14% alpha itself.
  expect(shadow!.backgroundColor, 'bg-primary/14 carries its 14% alpha').toContain('0.14');
  expect(shadow!.markerColor, 'the authored sheet inside the shadow root still applies').not.toBe(
    '',
  );
});

test('no reset came with the entry the application asked for', async ({ page }) => {
  // The application declared the entry, so the reset IS part of the contract
  // here — and it must be the engine's own, applied once, in the document.
  const boxSizing = await page.evaluate(() => getComputedStyle(document.body).boxSizing);
  expect(boxSizing, 'the declared document reset is in effect').toBe('border-box');
});

test('the document links exactly one document sheet and the DSD one component sheet', async ({
  page,
}) => {
  const state = await page.evaluate(() => {
    const head = [...document.head.querySelectorAll('link[rel="stylesheet"]')].map((link) => ({
      href: (link as HTMLLinkElement).getAttribute('href') ?? '',
      marked: link.hasAttribute('data-oe-static-styles'),
    }));
    const host = document.querySelector('probe-unocss-card');
    const inRoot = [...(host?.shadowRoot?.querySelectorAll('link[rel="stylesheet"]') ?? [])].map(
      (link) => ({
        href: (link as HTMLLinkElement).getAttribute('href') ?? '',
        marked: link.hasAttribute('data-oe-static-styles'),
      }),
    );
    return { head, inRoot };
  });
  // One unmarked head link: the generated document sheet (authored sheets are
  // marked). Nothing else in the head is a stylesheet.
  expect(state.head.filter((entry) => !entry.marked).length).toBe(1);
  // The shadow component declares its own sheets inside its template, where a
  // document-level rule cannot reach.
  expect(state.inRoot.length).toBeGreaterThanOrEqual(1);
  expect(state.inRoot.every((entry) => entry.marked)).toBe(true);
});
